import{_ as o,o as t,c as a,ag as r}from"./chunks/framework.rAhUSuuf.js";const h=JSON.parse('{"title":"Policies and Procedures","description":"","frontmatter":{},"headers":[],"relativePath":"policies-and-procedures.md","filePath":"policies-and-procedures.md","lastUpdated":1788159213000}'),s={name:"policies-and-procedures.md"};function n(i,e,l,c,d,p){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="policies-and-procedures" tabindex="-1">Policies and Procedures <a class="header-anchor" href="#policies-and-procedures" aria-label="Permalink to &quot;Policies and Procedures&quot;">​</a></h1><p><em>Last updated: FY 2083/84</em></p><p>These policies apply to everyone at Skybase — full-time, part-time, interns, and contractors. They set the minimum standard for how we protect company data, client work, and each other&#39;s accounts. Follow them from day one and keep them current as tools or roles change.</p><p>Questions about a specific tool? Raise a <strong>ticket</strong> on <a href="https://karyabase.com" target="_blank" rel="noreferrer">Karyabase</a> or contact the <strong>Operations Manager</strong>.</p><hr><h2 id="two-factor-authentication-2fa" tabindex="-1">Two-Factor Authentication (2FA) <a class="header-anchor" href="#two-factor-authentication-2fa" aria-label="Permalink to &quot;Two-Factor Authentication (2FA)&quot;">​</a></h2><p><strong>2FA is mandatory</strong> on every work account. No exceptions.</p><p>Enable 2FA before you use any tool for company work. Prefer an <strong>authenticator app</strong> (Google Authenticator, Authy, 1Password, or similar). Use SMS or email only when the service does not support an app.</p><table tabindex="0"><thead><tr><th>Tool</th><th>2FA required</th><th>Notes</th></tr></thead><tbody><tr><td>Company email (<code>@skybase.com.np</code>)</td><td>Yes</td><td>Set up when you claim your address</td></tr><tr><td><a href="https://discord.com" target="_blank" rel="noreferrer">Discord</a></td><td>Yes</td><td>Use your company email account only</td></tr><tr><td><a href="https://github.com" target="_blank" rel="noreferrer">GitHub</a></td><td>Yes</td><td>Required before repo access is granted</td></tr><tr><td><a href="https://karyabase.com" target="_blank" rel="noreferrer">Karyabase</a></td><td>Yes</td><td>Enable as soon as your account is active</td></tr><tr><td>Any other communication or PM tool</td><td>Yes</td><td>Slack, Figma, cloud consoles, client portals — if we use it for work, 2FA is on</td></tr></tbody></table><p>If you lose access to your 2FA device, contact the <strong>Operations Manager</strong> immediately. Do not disable 2FA to &quot;fix&quot; login issues on your own.</p><hr><h2 id="password-policy" tabindex="-1">Password Policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password Policy&quot;">​</a></h2><p>Use <strong>strong, unique passwords</strong> for every work account. Never reuse a password across services.</p><h3 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h3><ul><li><strong>Minimum 12 characters</strong></li><li>Mix of <strong>uppercase</strong>, <strong>lowercase</strong>, <strong>numbers</strong>, and <strong>symbols</strong></li><li><strong>No dictionary words</strong> or obvious patterns (e.g. <code>Skybase2024!</code>)</li><li><strong>No sharing</strong> — not with coworkers, not in Discord, not in tickets</li></ul><h3 id="update-schedule" tabindex="-1">Update schedule <a class="header-anchor" href="#update-schedule" aria-label="Permalink to &quot;Update schedule&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Account type</th><th>Maximum age</th><th>Action</th></tr></thead><tbody><tr><td><strong>Project management tools</strong> (Karyabase and similar)</td><td><strong>90 days</strong></td><td>Change password before expiry; update your password manager</td></tr><tr><td><strong>Communication tools</strong> (email, Discord)</td><td><strong>180 days</strong></td><td>Change on schedule or when the service prompts you</td></tr><tr><td><strong>GitHub and code platforms</strong></td><td><strong>180 days</strong></td><td>Same as above; also rotate if a key or token may be exposed</td></tr><tr><td><strong>Any account after a suspected breach</strong></td><td><strong>Immediately</strong></td><td>Change password and notify the Operations Manager</td></tr></tbody></table><p>We recommend a <strong>password manager</strong> (1Password, Bitwarden, or equivalent) so you can keep unique passwords without writing them down.</p><hr><h2 id="communication-tools" tabindex="-1">Communication Tools <a class="header-anchor" href="#communication-tools" aria-label="Permalink to &quot;Communication Tools&quot;">​</a></h2><h3 id="company-email" tabindex="-1">Company email <a class="header-anchor" href="#company-email" aria-label="Permalink to &quot;Company email&quot;">​</a></h3><ul><li>Use <strong><code>name@skybase.com.np</code></strong> for all official communication, sign-ups, and audit trails.</li><li>Do not use a personal email for work accounts or client correspondence.</li><li>Do not forward confidential company or client information to personal inboxes.</li><li>Report suspicious emails (phishing, impersonation) to the Operations Manager — do not click links or open attachments from unknown senders.</li></ul><h3 id="discord" tabindex="-1">Discord <a class="header-anchor" href="#discord" aria-label="Permalink to &quot;Discord&quot;">​</a></h3><ul><li>Create and use Discord with your <strong>company email</strong> only. Keep work and personal Discord accounts separate.</li><li>Enable <strong>2FA</strong> before joining the company server.</li><li>Do not share invite links publicly or with people outside the team.</li><li>Use appropriate channels — sensitive or client-specific topics belong in designated private channels, not <code>#general</code>.</li><li>Daily work updates belong in <strong>Karyabase</strong>, not Discord. See <a href="/daily-updates.html">Daily Work Updates</a>.</li></ul><h3 id="karyabase" tabindex="-1">Karyabase <a class="header-anchor" href="#karyabase" aria-label="Permalink to &quot;Karyabase&quot;">​</a></h3><ul><li>Log in only with credentials issued to you. Do not share your login with anyone.</li><li>Post <strong>leave requests</strong>, <strong>attendance corrections</strong>, <strong>tickets</strong>, and <strong>daily updates</strong> here — not in chat.</li><li>Change your password on the <strong>90-day schedule</strong> above.</li><li>Log out on shared or public devices.</li></ul><hr><h2 id="github-and-development-access" tabindex="-1">GitHub and Development Access <a class="header-anchor" href="#github-and-development-access" aria-label="Permalink to &quot;GitHub and Development Access&quot;">​</a></h2><ul><li><strong>2FA is required</strong> on your work GitHub account before you push code or access private repos.</li><li>Use <strong>SSH keys with a passphrase</strong> when working with multiple accounts. See <a href="/git-multi-accounts.html">Git Multi Accounts</a>.</li><li>Never commit <strong>secrets</strong> (API keys, passwords, <code>.env</code> files with live credentials) to any repository.</li><li>Revoke access tokens and SSH keys you no longer need.</li><li>Report lost devices, leaked keys, or accidental secret commits to the Operations Manager at once.</li></ul><p>For branching, commits, and versioning standards, see <a href="/git-conventions.html">Git Conventions</a> and <a href="/conventions.html">Version Conventions</a>.</p><hr><h2 id="device-and-workspace-security" tabindex="-1">Device and Workspace Security <a class="header-anchor" href="#device-and-workspace-security" aria-label="Permalink to &quot;Device and Workspace Security&quot;">​</a></h2><ul><li><strong>Lock your screen</strong> when you step away — at the office or when working remotely.</li><li>Keep your <strong>operating system and browsers updated</strong> on machines used for company work.</li><li>Do not install <strong>unapproved software</strong> on company-provided devices without Management approval.</li><li>Do not store company or client data on <strong>personal cloud drives</strong> (Google Drive, Dropbox, iCloud, etc.) unless explicitly approved.</li><li>Use <strong>company-approved channels</strong> for file sharing and backups.</li><li>On public or shared networks, avoid accessing sensitive systems without a secure connection when one is provided by the company.</li></ul><hr><h2 id="acceptable-use" tabindex="-1">Acceptable Use <a class="header-anchor" href="#acceptable-use" aria-label="Permalink to &quot;Acceptable Use&quot;">​</a></h2><p>Company accounts, devices, and infrastructure exist for <strong>work purposes</strong>.</p><ul><li>Do not use company resources for illegal activity, harassment, or content that damages the company&#39;s reputation.</li><li>Do not attempt to bypass security controls, scrape internal systems without permission, or access data outside your role.</li><li>Client work stays <strong>confidential</strong> — see <a href="/about.html">About Your Employment</a> and <a href="/accident.html">Accidents, Misconduct and Disputes</a> for broader conduct expectations.</li></ul><hr><h2 id="reporting-security-issues" tabindex="-1">Reporting Security Issues <a class="header-anchor" href="#reporting-security-issues" aria-label="Permalink to &quot;Reporting Security Issues&quot;">​</a></h2><p>Report any of the following <strong>immediately</strong> (same day, without waiting):</p><ul><li>Lost or stolen laptop, phone, or 2FA device</li><li>Suspected phishing or account takeover</li><li>Accidental exposure of credentials, API keys, or client data</li><li>Unauthorized access to a system or repository</li></ul><p><strong>How to report:</strong> message the <strong>Operations Manager</strong> on Discord and raise a <strong>ticket</strong> on <a href="https://karyabase.com" target="_blank" rel="noreferrer">Karyabase</a> with what happened, when, and what you have already done (e.g. password changed).</p><p>We treat good-faith reports seriously. Fixing a mistake quickly is always better than hiding it.</p><hr><h2 id="compliance" tabindex="-1">Compliance <a class="header-anchor" href="#compliance" aria-label="Permalink to &quot;Compliance&quot;">​</a></h2><p>Following these policies is part of your employment responsibilities.</p><ul><li>Management may <strong>audit</strong> that 2FA and password standards are in place on work accounts.</li><li>Repeated or deliberate failure to comply may result in <strong>warnings</strong>, <strong>revoked access</strong>, or <strong>termination</strong>, depending on severity — especially where client data or company security is put at risk.</li><li>When in doubt, ask before you share, install, or connect something new to company systems.</li></ul>',47)])])}const g=o(s,[["render",n]]);export{h as __pageData,g as default};
